//
// libSceMouse is linked directly, like libSceKeyboard in input.cpp: the import
// stub is generated by tools/make-stub.sh on every build (src/mouse.cpp uses
// the mouse in the normal app too; the two handles are independent), and the
// module is loaded with sceSysmoduleLoadModule(0x00a9) before the first call,
// the way input.cpp loads the keyboard (0x0106). 0x00a9 -> libSceMouse.sprx
// was measured on FW 13.60 with research/vdev "sysmod 0x00a9".
#include "research.hpp"
#include "platform/native_probe.hpp"

#ifndef PS5TERM_RESEARCH
namespace term
{
void Research::tick(TerminalModel &, std::uint64_t now) noexcept
{
    platform::tick_native_capabilities(now);
}
void Research::keyboard(std::uint32_t, const std::uint16_t *, int, bool, bool) noexcept
{
}
} // namespace term
#else
#include "terminal_model.hpp"
#include <cstdio>
#include <cstring>
#include <ctime>
#include <fcntl.h>
#include <sys/stat.h>
#include <unistd.h>
extern "C"
{
    int sceSysmoduleLoadModule(std::uint16_t id);
    int sceUserServiceGetInitialUser(int *user);
    int sceMouseInit();
    int sceMouseOpen(int user, int type, int index, const void *param);
    int sceMouseRead(int handle, void *data, int count);
    int sceMouseClose(int handle);
}
namespace term
{
namespace
{
constexpr const char *directory = "/data/ps5term";
constexpr const char *command_file = "/data/ps5term/research.cmd";
constexpr const char *monitor_file = "/data/ps5term/vdev-monitor.txt";
constexpr unsigned default_seconds = 300;
constexpr std::uint16_t sysmodule_mouse = 0x00a9;

struct MouseData // SceMouseData
{
    std::uint64_t timestamp;
    std::uint8_t connected;
    std::uint8_t pad0[3];
    std::uint32_t buttons;
    std::int32_t x, y, wheel, tilt;
    std::uint8_t reserved[8];
};
static_assert(sizeof(MouseData) == 40);

std::uint64_t monotonic_us() noexcept
{
    timespec t{};
    clock_gettime(CLOCK_MONOTONIC, &t);
    return static_cast<std::uint64_t>(t.tv_sec) * 1000000 +
           static_cast<std::uint64_t>(t.tv_nsec) / 1000;
}
} // namespace

// One line: "t=<CLOCK_MONOTONIC us> <text>", on screen and in the log file.
void Research::log(const char *text) noexcept
{
    char line[320];
    int n = std::snprintf(line, sizeof(line), "t=%llu %s\n",
                          static_cast<unsigned long long>(monotonic_us()), text);
    if (n <= 0)
        return;
    std::size_t size =
        static_cast<std::size_t>(n) < sizeof(line) ? static_cast<std::size_t>(n) : sizeof(line) - 1;
    if (model_)
        model_->feed({line, size});
    if (fd_ >= 0)
        (void)::write(fd_, line, size);
}

void Research::tick(TerminalModel &model, std::uint64_t now) noexcept
{
    platform::tick_native_capabilities(now);
    model_ = &model;
    if (!started_)
    {
        started_ = true;
        start_monitor(now, default_seconds);
    }
    if (pending_[0])
    {
        char command[128];
        std::memcpy(command, pending_.data(), sizeof(command));
        pending_[0] = 0;
        run(command + 5, now); // strip "vdev "
    }
    if (now >= next_poll_)
    {
        next_poll_ = now + 1000000;
        int fd = ::open(command_file, O_RDONLY);
        if (fd >= 0)
        {
            char buffer[128]{};
            auto n = ::read(fd, buffer, sizeof(buffer) - 1);
            ::close(fd);
            ::unlink(command_file);
            if (n > 0)
            {
                buffer[n] = 0;
                char *line = buffer;
                while (*line)
                {
                    char *end = line;
                    while (*end && *end != '\n' && *end != '\r')
                        ++end;
                    char saved = *end;
                    *end = 0;
                    if (*line)
                        run(line, now);
                    if (!saved)
                        break;
                    line = end + 1;
                }
            }
        }
    }
    if (monitor_)
    {
        if (now >= monitor_until_)
            stop_monitor("time limit");
        else
        {
            open_mouse(now);
            poll_mouse();
        }
    }
}

void Research::run(std::string_view command, std::uint64_t now) noexcept
{
    if (command == "monitor off")
        stop_monitor("stopped");
    else if (command.substr(0, 7) == "monitor")
    {
        unsigned seconds = 0;
        for (char ch : command.substr(7))
            if (ch >= '0' && ch <= '9')
                seconds = seconds * 10 + static_cast<unsigned>(ch - '0');
        start_monitor(now, seconds ? seconds : default_seconds);
    }
    else if (model_)
        model_->feed("[vdev] commands: monitor [seconds] | monitor off\n");
}

void Research::start_monitor(std::uint64_t now, unsigned seconds) noexcept
{
    char text[160];
    monitor_until_ = now + static_cast<std::uint64_t>(seconds) * 1000000;
    if (monitor_)
    {
        std::snprintf(text, sizeof(text), "[mon] extended: %u s", seconds);
        log(text);
        return;
    }
    ::mkdir(directory, 0700);
    fd_ = ::open(monitor_file, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    monitor_ = true;
    raw_dumps_ = mouse_events_ = kb_events_ = 0;
    mouse_buttons_ = 0;
    mouse_connected_ = 0;
    kb_keys_ = {};
    kb_modifiers_ = 0;
    kb_connected_ = false;
    next_open_ = 0;
    std::snprintf(text, sizeof(text), "[mon] PS5Term monitoring mouse + keyboard for %u s",
                  seconds);
    log(text);
    if (!mouse_loaded_)
    {
        int rc = sceSysmoduleLoadModule(sysmodule_mouse);
        std::snprintf(text, sizeof(text), "[mon] sceSysmoduleLoadModule(0x%04x)=0x%08x",
                      sysmodule_mouse, static_cast<unsigned>(rc));
        log(text);
        if (rc == 0)
        {
            mouse_loaded_ = true;
            std::snprintf(text, sizeof(text), "[mon] sceMouseInit=0x%08x",
                          static_cast<unsigned>(sceMouseInit()));
            log(text);
        }
    }
}

void Research::open_mouse(std::uint64_t now) noexcept
{
    if (!mouse_loaded_ || mouse_ >= 0 || now < next_open_)
        return;
    next_open_ = now + 2000000;
    if (user_ < 0)
        sceUserServiceGetInitialUser(&user_);
    std::uint8_t param[8]{};
    int rc = sceMouseOpen(user_, 0, 0, param);
    if (rc >= 0)
        mouse_ = rc;
    if (rc >= 0 || rc != last_open_rc_)
    {
        char text[128];
        std::snprintf(text, sizeof(text), "[mon] sceMouseOpen(user 0x%08x)=0x%08x",
                      static_cast<unsigned>(user_), static_cast<unsigned>(rc));
        log(text);
    }
    last_open_rc_ = rc;
}

void Research::stop_monitor(const char *why) noexcept
{
    if (!monitor_)
        return;
    char text[160];
    if (mouse_ >= 0)
    {
        std::snprintf(text, sizeof(text), "[mon] sceMouseClose=0x%08x",
                      static_cast<unsigned>(sceMouseClose(mouse_)));
        log(text);
    }
    mouse_ = -1;
    std::snprintf(text, sizeof(text), "[mon] monitor %s; %u mouse samples, %u keyboard changes",
                  why, mouse_events_, kb_events_);
    log(text);
    monitor_ = false;
    if (fd_ >= 0)
        ::close(fd_);
    fd_ = -1;
}

void Research::poll_mouse() noexcept
{
    if (mouse_ < 0)
        return;
    // Roomy buffer: if this firmware's sample were larger than 40 bytes, the
    // first raw dumps would show the real stride.
    alignas(8) std::uint8_t buffer[16 * 128]{};
    int n = sceMouseRead(mouse_, buffer, 16);
    char text[288];
    if (n < 0)
    {
        if (raw_dumps_ < 1)
        {
            ++raw_dumps_;
            std::snprintf(text, sizeof(text), "[mon] sceMouseRead=0x%08x",
                          static_cast<unsigned>(n));
            log(text);
        }
        return;
    }
    for (int i = 0; i < n && i < 16; ++i)
    {
        MouseData s;
        std::memcpy(&s, buffer + i * sizeof(MouseData), sizeof(s));
        bool moved = s.x || s.y || s.wheel || s.tilt;
        if (!moved && s.buttons == mouse_buttons_ && s.connected == mouse_connected_)
            continue;
        if (raw_dumps_ < 4)
        {
            ++raw_dumps_;
            int used = std::snprintf(text, sizeof(text), "[mon] raw n=%d #%d:", n, i);
            for (unsigned b = 0; b < 48 && used > 0 && used < static_cast<int>(sizeof(text)) - 4;
                 ++b)
                used += std::snprintf(text + used, sizeof(text) - static_cast<std::size_t>(used),
                                      " %02x", buffer[i * sizeof(MouseData) + b]);
            log(text);
        }
        ++mouse_events_;
        std::snprintf(text, sizeof(text),
                      "[mouse] conn=%u buttons=0x%x dx=%d dy=%d wheel=%d tilt=%d sample_ts=%llu",
                      s.connected, s.buttons, s.x, s.y, s.wheel, s.tilt,
                      static_cast<unsigned long long>(s.timestamp));
        log(text);
        mouse_buttons_ = s.buttons;
        mouse_connected_ = s.connected;
    }
}

void Research::keyboard(std::uint32_t modifiers, const std::uint16_t *keys, int count,
                        bool connected, bool intercepted) noexcept
{
    if (!monitor_)
        return;
    std::array<std::uint16_t, 16> now{};
    for (int i = 0; i < count && i < 16; ++i)
        now[static_cast<std::size_t>(i)] = keys[i];
    if (now == kb_keys_ && modifiers == kb_modifiers_ && connected == kb_connected_)
        return;
    ++kb_events_;
    char text[160];
    std::snprintf(text, sizeof(text),
                  "[keyboard] conn=%u intercepted=%u mods=0x%02x keys=%u %u %u %u %u %u",
                  connected ? 1 : 0, intercepted ? 1 : 0, modifiers, now[0], now[1], now[2], now[3],
                  now[4], now[5]);
    log(text);
    kb_keys_ = now;
    kb_modifiers_ = modifiers;
    kb_connected_ = connected;
}
} // namespace term
#endif // PS5TERM_RESEARCH
